import '@testing-library/jest-dom/vitest'

import { configureStore } from '@reduxjs/toolkit'
import { act, render, screen } from '@testing-library/react'
import { Provider } from 'react-redux'
import { MemoryRouter, Route, Routes } from 'react-router-dom'
import { describe, expect, it, vi } from 'vitest'

vi.mock('../services/apiClient', () => ({
  apiClient: { post: vi.fn() },
  setSessionTokens: vi.fn(),
  restoreStoredSession: vi.fn(),
}))

import authReducer, { restoreSession, type SessionUser } from '../store/slices/authSlice'
import { RouteGuard } from './RouteGuard'

const doctor: SessionUser = { id: 'synthetic-doctor-01', name: 'Synthetic Doctor', role: 'DOCTOR', verificationStatus: 'VERIFIED' }

function renderGuarded() {
  const store = configureStore({ reducer: { auth: authReducer } })
  store.dispatch(restoreSession.pending('synthetic-request'))
  render(
    <Provider store={store}>
      <MemoryRouter initialEntries={['/approvals']}>
        <Routes>
          <Route path="/login" element={<h1>Sign in</h1>} />
          <Route path="/approvals" element={<RouteGuard allowedRoles={['DOCTOR']}><h1>Approvals</h1></RouteGuard>} />
        </Routes>
      </MemoryRouter>
    </Provider>,
  )
  return store
}

describe('RouteGuard while a reloaded session is restored', () => {
  it('waits instead of redirecting, then shows the page once the session returns', () => {
    const store = renderGuarded()

    expect(screen.getByRole('status')).toHaveTextContent(/restoring your session/i)
    expect(screen.queryByRole('heading', { name: 'Sign in' })).not.toBeInTheDocument()

    act(() => { store.dispatch(restoreSession.fulfilled(doctor, 'synthetic-request')) })
    expect(screen.getByRole('heading', { name: 'Approvals' })).toBeInTheDocument()
  })

  it('sends the person to sign in when the session cannot be restored', () => {
    const store = renderGuarded()

    act(() => { store.dispatch(restoreSession.fulfilled(null, 'synthetic-request')) })
    expect(screen.getByRole('heading', { name: 'Sign in' })).toBeInTheDocument()
  })
})
